export const SERVICES = SITE.serviceGroups.flatMap((g) =>
  g.services.map((s) => ({ ...s, group: g.title, groupId: g.id }))
);

export function findService(slug) {
  return SERVICES.find((s) => s.slug === slug) || null;
}

export function findBarber(slug) {
  return SITE.barbers.find((b) => b.slug === slug) || null;
}
